import numpy as np

class GSLMatrix:
    def __init__(self, self, rows, cols):
        self._ptr = None
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self._ptr = gsl.gsl_matrix_alloc(self.rows, self.cols)

    def free(self):
        gsl.gsl_matrix_free(self._ptr)

    def to_numpy(self):
        return np.ctypeslib.as_array(self._ptr)

    def __getitem__(self, key):
      if isinstance(key, tuple):
          row, col = key
          return self._ptr[row * self.cols + col]
      else:
        raise ValueError("Invalid index type")


def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0])
    matrix = GSLMatrix(rows, cols)
    for i in range(rows):
      for j in range(cols):
        matrix._ptr[i * cols + j] = lst[i][j]
    return matrix


