def matrix_to_gsl(matrix: List[List[float]]) -> gsl.gsl_matrix_view:
  rows = len(matrix)
  cols = len(matrix[0])
  data = (ctypes.c_double * rows * cols)(*matrix[i][j] for i in range(rows) for j in range(cols))
  return gsl.gsl_matrix_view(None, rows, cols, data)

def vector_to_gsl(vector: List[float]) -> gsl.gsl_vector_view:
  return gsl.gsl_vector_view(None, len(vector), *vector)

def gsl_matrix_to_list(matrix: gsl.gsl_matrix_view) -> List[List[float]]:
  return [[matrix.data[i * matrix.cols + j] for j in range(matrix.cols)] for i in range(matrix.rows)]

def gsl_vector_to_list(vector: gsl.gsl_vector_view) -> List[float]:
  return [vector.data[i] for i in range(vector.size)]
def ql_decomposition_and_unpack(A: List[List[float]], tau: List[float]) -> Tuple[List[List[float]], List[List[float]]]:
